create or replace function school_private.duel_finish(p_room_id uuid, p_reason text, p_forfeit uuid default null)
returns void language plpgsql security definer set search_path = '' as $$
declare r school_private.duel_rooms%rowtype; h int; g int; winner uuid;
begin
  select * into r from school_private.duel_rooms where id = p_room_id for update;
  if r.status <> 'active' then return; end if;
  select count(*) filter (where correct)::int into h from school_private.duel_answers where room_id = r.id and user_id = r.host_id;
  select count(*) filter (where correct)::int into g from school_private.duel_answers where room_id = r.id and user_id = r.guest_id;
  if r.activity is not null then
 select coalesce(sum(points),0)::int into h from school_private.duel_answers where room_id=r.id and user_id=r.host_id;
 select coalesce(sum(points),0)::int into g from school_private.duel_answers where room_id=r.id and user_id=r.guest_id;
 end if;
 winner := case when p_forfeit = r.host_id then r.guest_id when p_forfeit = r.guest_id then r.host_id
    when h > g then r.host_id when g > h then r.guest_id else null end;
  update school_private.duel_rooms set status = 'completed', finished_at = clock_timestamp(),
    result = jsonb_build_object('winner_id', winner, 'reason', p_reason, 'scores', jsonb_build_array(
      jsonb_build_object('id', r.host_id, 'name', r.host_name, 'score', h),
      jsonb_build_object('id', r.guest_id, 'name', r.guest_name, 'score', g))) where id = r.id;
end;
$$;
create or replace function school_private.duel_snapshot(p_room_id uuid, p_uid uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare r school_private.duel_rooms%rowtype; h int; g int; hs int; gs int; own_count int; total int; metadata jsonb; receipts jsonb; q jsonb; players jsonb; me jsonb;
begin
  select * into r from school_private.duel_rooms where id = p_room_id;
  if not found or p_uid not in (r.host_id, coalesce(r.guest_id, r.host_id)) then
    raise exception 'room_not_found' using errcode = '42501';
  end if;
  select count(*)::int, count(*) filter(where correct)::int into h, hs from school_private.duel_answers where room_id = r.id and user_id = r.host_id;
  select count(*)::int, count(*) filter(where correct)::int into g, gs from school_private.duel_answers where room_id = r.id and user_id = r.guest_id;
  total:=jsonb_array_length(r.questions);
  if r.activity is not null then
   select count(*) filter(where (r.activity->>'game')::int<>2 or correct)::int,coalesce(sum(points),0)::int into h,hs from school_private.duel_answers where room_id=r.id and user_id=r.host_id;
   select count(*) filter(where (r.activity->>'game')::int<>2 or correct)::int,coalesce(sum(points),0)::int into g,gs from school_private.duel_answers where room_id=r.id and user_id=r.guest_id;
  end if;
  own_count := case when p_uid = r.host_id then h else g end;
  players := jsonb_build_array(jsonb_build_object('id',r.host_id,'name',r.host_name,'answered',h,'score',case when r.status = 'completed' then hs else null end,'finished',h = total));
  if r.guest_id is not null then players := players || jsonb_build_array(jsonb_build_object('id',r.guest_id,'name',r.guest_name,'answered',g,'score',case when r.status = 'completed' then gs else null end,'finished',g = total)); end if;
  select value into me from jsonb_array_elements(players) where value ->> 'id' = p_uid::text;
  if r.status = 'active' and own_count < total then
    q := r.questions -> own_count;
    -- Never return the answer key or explanation during the duel.
    q := jsonb_build_object('id',q -> 'id','prompt',q -> 'prompt','options',q -> 'options');
  end if;
  if r.activity is not null then
   select coalesce(jsonb_agg(jsonb_build_object('id',question_id,'response',response,'correct',correct,'points',points,'at',answered_at) order by answered_at),'[]') into receipts from school_private.duel_answers where room_id=r.id and user_id=p_uid;
   me:=me || jsonb_build_object('receipts',receipts,'finished',own_count>=total or exists(select 1 from school_private.educational_finishes where room_id=r.id and user_id=p_uid));
   metadata:=r.activity || jsonb_build_object('ids',(select jsonb_agg(x->'id') from jsonb_array_elements(r.questions) x),'terms',(select jsonb_agg(x->'term') from jsonb_array_elements(r.questions) x),'sequences',(select jsonb_agg(coalesce(x->'sequence','[]')) from jsonb_array_elements(r.questions) x));
  end if;
  return jsonb_build_object('id',r.id,'code',r.code,'status',r.status,'host_id',r.host_id,'guest_id',r.guest_id,
    'created_at',r.created_at,'expires_at',r.expires_at,'started_at',r.started_at,'deadline',r.deadline,
    'finished_at',r.finished_at,'server_now',clock_timestamp(),'question_count',total,'players',players,'me',me,'question',q,'result',r.result,'activity',metadata);
end;
$$;
create or replace function public.duel_join(p_code text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid; r school_private.duel_rooms%rowtype; other uuid; display text;
begin
  u := school_private.duel_identity();
  perform pg_advisory_xact_lock(hashtextextended(u::text,744));
  if p_code is null or upper(btrim(p_code)) !~ '^[A-F0-9]{10}$' then raise exception 'invalid_room_code' using errcode = '22023'; end if;
  select * into r from school_private.duel_rooms where code = upper(btrim(p_code)) for update;
  if not found then raise exception 'room_not_found' using errcode = '22023'; end if;
  if r.host_id = u then raise exception 'cannot_join_own_room' using errcode = '22023'; end if;
  if r.guest_id = u then perform school_private.duel_settle(r.id); return school_private.duel_snapshot(r.id,u); end if;
  perform school_private.duel_settle(r.id);
  select * into r from school_private.duel_rooms where id = r.id;
  if r.status <> 'waiting' or r.guest_id is not null then raise exception 'room_unavailable' using errcode = '22023'; end if;
  for other in select id from school_private.duel_rooms where (host_id = u or guest_id = u) and status in ('waiting','active') loop
    perform school_private.duel_settle(other);
  end loop;
  if exists(select 1 from school_private.duel_rooms where (host_id = u or guest_id = u) and status in ('waiting','active')) then raise exception 'already_in_room' using errcode = '22023'; end if;
  select display_name into display from public.student_profiles where id = u;
  update school_private.duel_rooms set guest_id = u, guest_name = coalesce(display,'لاعب'), status = 'active',
    started_at = clock_timestamp(), deadline = clock_timestamp() + make_interval(secs=>coalesce((r.activity->>'seconds')::int,90)) where id = r.id;
  return school_private.duel_snapshot(r.id,u);
end;
$$;
create or replace function public.platform_admin_duels(p_limit int default 20, p_offset int default 0)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare room_id uuid; result jsonb; total bigint;
begin
  if not school_private.is_admin() then raise exception 'administrator_required' using errcode = '42501'; end if;
  if p_limit is null or p_offset is null or p_limit < 1 or p_limit > 100 or p_offset < 0 then raise exception 'invalid_pagination' using errcode = '22023'; end if;
  -- Settle stale rooms on the requested page; no background daemon is needed.
  for room_id in select id from school_private.duel_rooms order by created_at desc, id limit p_limit offset p_offset loop
    perform school_private.duel_settle(room_id);
  end loop;
  select count(*) into total from school_private.duel_rooms;
  select coalesce(jsonb_agg(row_data),'[]') into result from (
    select jsonb_build_object('id',r.id,'code',r.code,'status',r.status,'created_at',r.created_at,'started_at',r.started_at,'finished_at',r.finished_at,
      'host_id',r.host_id,'host_name',r.host_name,'host_email',h.email,'guest_id',r.guest_id,'guest_name',r.guest_name,'guest_email',g.email,'result',r.result,'activity',r.activity) row_data
    from school_private.duel_rooms r left join auth.users h on h.id = r.host_id left join auth.users g on g.id = r.guest_id
    order by r.created_at desc, r.id limit p_limit offset p_offset
  ) page;
  return jsonb_build_object('rooms',result,'total',total,'limit',p_limit,'offset',p_offset);
end;
$$;

create or replace function public.educational_duel_create(p_game int,p_unit text,p_lesson text,p_seconds int)
returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid;r uuid; qs jsonb:='[]';c text;display text;limit_n int; item jsonb;seq jsonb; i int:=0;
begin
 u:=school_private.duel_identity();
 if p_game is null or p_game not between 0 and 12 or p_seconds is null or p_seconds not between 15 and 1800 or p_unit is null or p_unit !~ '^(all|u0[1-4])$' or p_lesson is null or p_lesson !~ '^(all|u0[1-4]_l[0-9]{2})$' or (p_lesson<>'all' and p_unit<>'all' and left(p_lesson,3)<>p_unit) then raise exception 'invalid_activity_settings' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(u::text,744));
 for r in select id from school_private.duel_rooms where (host_id=u or guest_id=u) and status in('waiting','active') order by created_at loop perform school_private.duel_settle(r);end loop;
 select id into r from school_private.duel_rooms where (host_id=u or guest_id=u) and status in('waiting','active') limit 1;
 if r is not null then return school_private.duel_snapshot(r,u);end if;
 if (select count(*) from school_private.duel_rooms where host_id=u and created_at>clock_timestamp()-interval '1 hour')>=20 then raise exception 'room_rate_limit' using errcode='22023';end if;
 limit_n:=case p_game when 0 then 15 when 2 then 5 when 5 then 12 when 9 then 5 else 8 end;
 for item in select data from (select data from school_private.educational_questions where game=p_game and (p_unit='all' or unit_id=p_unit) and(p_lesson='all' or lesson_id=p_lesson) order by random() limit limit_n) x order by case when p_game in(0,10) then case data->>'difficulty' when 'easy' then 1 when 'medium' then 2 else 3 end else 0 end loop
  if p_game=12 then
   select jsonb_agg(x->'id') into seq from (select x from jsonb_array_elements(item->'payload'->'left') x order by random() limit 2+i) a;
   item:=item||jsonb_build_object('sequence',seq);
  end if;
  qs:=qs||jsonb_build_array(item);i:=i+1;
 end loop;
 if i=0 or(p_game=2 and i<5) then raise exception 'activity_content_unavailable' using errcode='55000';end if;
 select display_name into display from public.student_profiles where id=u;
 loop
  c:=upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));
  begin
   insert into school_private.duel_rooms(code,host_id,host_name,questions,activity) values(c,u,coalesce(display,'لاعب'),qs,jsonb_build_object('game',p_game,'unit',p_unit,'lesson',p_lesson,'seconds',p_seconds)) returning id into r;exit;
  exception when unique_violation then null;end;
 end loop;
 return school_private.duel_snapshot(r,u);
end;$$;

create or replace function school_private.educational_answer(p_room uuid,p_uid uuid,p_question text,p_response jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r school_private.duel_rooms%rowtype;q jsonb;old school_private.duel_answers%rowtype;n int;pos int;game int;correct boolean:=false;expected jsonb;pts int:=0;value jsonb;term text;
begin
 select * into r from school_private.duel_rooms where id=p_room for update;
 if p_uid is distinct from auth.uid() or p_uid not in(r.host_id,coalesce(r.guest_id,r.host_id)) then raise exception 'room_not_found' using errcode='42501';end if;
 game:=(r.activity->>'game')::int;
 select * into old from school_private.duel_answers where room_id=r.id and user_id=p_uid and question_id=p_question;
 if found and (old.correct or game<>2 or old.response=p_response) then
  if old.response is distinct from p_response then raise exception 'answer_already_submitted' using errcode='22023';end if;
  return school_private.duel_snapshot(r.id,p_uid);
 end if;
 if r.status<>'active' or exists(select 1 from school_private.educational_finishes where room_id=r.id and user_id=p_uid) then return school_private.duel_snapshot(r.id,p_uid);end if;
 if p_response is null or jsonb_typeof(p_response)<>'object' or octet_length(p_response::text)>10000 then raise exception 'invalid_activity_response' using errcode='22023';end if;
 select x,ord::int-1 into q,pos from jsonb_array_elements(r.questions) with ordinality a(x,ord) where x->>'id'=p_question;
 if q is null then raise exception 'question_out_of_scope' using errcode='22023';end if;
 select count(*) filter(where game<>2 or school_private.duel_answers.correct)::int into n from school_private.duel_answers where room_id=r.id and user_id=p_uid;
 if game not in(5,9) and (r.questions->n->>'id') is distinct from p_question then raise exception 'question_out_of_order' using errcode='22023';end if;
 value:=p_response->'answer';
 case q->>'type'
 when 'multiple_choice','fill_blank' then correct:=value=q->'answer'->'option_id';
 when 'true_false' then correct:=value=q->'answer'->'value';
 when 'ordering' then correct:=value=q->'answer'->'ordered_ids';
 when 'matching' then
  select jsonb_object_agg(x->>'left_id',x->'right_id') into expected from jsonb_array_elements(q->'answer'->'pairs') x;
  correct:=value=expected;
 else correct:=false;
 end case;
 if game in(7,9) then
  term:=regexp_replace(q->>'term','[\u064B-\u065F\u0670\u0640[:space:]]','','g');
  correct:=p_response->>'word'=term;
  if game=9 then correct:=correct and p_response->'start'=jsonb_build_array(pos,0) and p_response->'end'=jsonb_build_array(pos,char_length(term)-1);end if;
 end if;
 if game=11 then correct:=correct and jsonb_typeof(p_response->'pipes')='array' and jsonb_array_length(p_response->'pipes')=4;
  if correct then select bool_and(x in('0','2')) into correct from jsonb_array_elements_text(p_response->'pipes') x;end if;
 end if;
 if game=12 then correct:=correct and p_response->'sequence'=q->'sequence';end if;
 if game=6 then correct:=correct and p_response->'clues'=(select jsonb_agg(x->'id') from (select x from jsonb_array_elements(r.questions) with ordinality a(x,ord) where ord<=3 order by ord) a);end if;
 if game=3 then correct:=correct and p_response->'spun'='true'::jsonb;end if;
 correct:=coalesce(correct,false);
 if correct then pts:=case game when 0 then (round(1000000.0*(pos+1)/jsonb_array_length(r.questions))-round(1000000.0*pos/jsonb_array_length(r.questions)))::int when 5 then case q->>'difficulty' when 'easy' then 100 when 'medium' then 300 else 500 end else 100 end;end if;
 insert into school_private.duel_answers(room_id,user_id,question_id,response,correct,points) values(r.id,p_uid,p_question,p_response,correct,pts)
 on conflict(room_id,user_id,question_id) do update set response=excluded.response,correct=excluded.correct,points=excluded.points,answered_at=clock_timestamp();
 if (select count(*) from school_private.duel_answers where room_id=r.id and(game<>2 or school_private.duel_answers.correct))>=2*jsonb_array_length(r.questions) then perform school_private.duel_finish(r.id,'answered');end if;
 return school_private.duel_snapshot(r.id,p_uid);
end;$$;

create or replace function public.educational_duel_finish(p_room_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid;r school_private.duel_rooms%rowtype;done_h boolean;done_g boolean;
begin
 u:=school_private.duel_identity();select * into r from school_private.duel_rooms where id=p_room_id for update;
 if not found or u not in(r.host_id,coalesce(r.guest_id,r.host_id)) or r.activity is null then raise exception 'room_not_found' using errcode='42501';end if;
 perform school_private.duel_settle(r.id);select * into r from school_private.duel_rooms where id=p_room_id;
 if r.status='active' then
  insert into school_private.educational_finishes(room_id,user_id) values(r.id,u) on conflict do nothing;
  done_h:=exists(select 1 from school_private.educational_finishes where room_id=r.id and user_id=r.host_id) or (select count(*) from school_private.duel_answers where room_id=r.id and user_id=r.host_id and((r.activity->>'game')::int<>2 or correct))>=jsonb_array_length(r.questions);
  done_g:=exists(select 1 from school_private.educational_finishes where room_id=r.id and user_id=r.guest_id) or (select count(*) from school_private.duel_answers where room_id=r.id and user_id=r.guest_id and((r.activity->>'game')::int<>2 or correct))>=jsonb_array_length(r.questions);
  if done_h and done_g then perform school_private.duel_finish(r.id,'submitted');end if;
 end if;
 return school_private.duel_snapshot(r.id,u);
end;$$;
create or replace function public.duel_answer(p_room_id uuid, p_question_id text, p_answer jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare u uuid; r school_private.duel_rooms%rowtype; count_own int; q jsonb; old jsonb;
begin
  u := school_private.duel_identity();
  select * into r from school_private.duel_rooms where id = p_room_id for update;
  if not found or u not in(r.host_id,coalesce(r.guest_id,r.host_id)) then raise exception 'room_not_found' using errcode = '42501'; end if;
  perform school_private.duel_settle(r.id);
  select * into r from school_private.duel_rooms where id = p_room_id;
  if r.activity is not null then return school_private.educational_answer(r.id,u,p_question_id,p_answer); end if;
  -- A network retry of exactly the same submitted answer is idempotent.
  select response into old from school_private.duel_answers where room_id = r.id and user_id = u and question_id = p_question_id;
  if found then
    if old is distinct from p_answer then raise exception 'answer_already_submitted' using errcode = '22023'; end if;
    return school_private.duel_snapshot(r.id,u);
  end if;
  if r.status <> 'active' then return school_private.duel_snapshot(r.id,u); end if;
  select count(*)::int into count_own from school_private.duel_answers where room_id = r.id and user_id = u;
  q := r.questions -> count_own;
  if q is null or p_question_id is distinct from q ->> 'id' then raise exception 'question_out_of_order' using errcode = '22023'; end if;
  if p_answer is null or jsonb_typeof(p_answer) <> 'string' or not exists(select 1 from jsonb_array_elements(q -> 'options') x where x -> 'id' = p_answer) then
    raise exception 'invalid_answer' using errcode = '22023';
  end if;
  insert into school_private.duel_answers(room_id,user_id,question_id,response,correct) values(r.id,u,p_question_id,p_answer,p_answer = q -> 'correct_answer');
  if (select count(*) from school_private.duel_answers where room_id = r.id) = 10 then perform school_private.duel_finish(r.id,'answered'); end if;
  return school_private.duel_snapshot(r.id,u);
end;
$$;revoke all on function school_private.educational_answer(uuid,uuid,text,jsonb) from public,anon,authenticated;
revoke all on function public.educational_duel_create(int,text,text,int),public.educational_duel_finish(uuid) from public,anon,authenticated;
grant execute on function public.educational_duel_create(int,text,text,int),public.educational_duel_finish(uuid) to authenticated;
